// ─── Normalize Lead for Scoring v2 ─────────────────────────────────────────
// Accepts leads from Flow #2 (all channels) and Flow #1 (Radar)
const lead = $input.first().json;

// ── Identify source type ─────────────────────────────────────────────────────
const rawSource = lead.source || 'Form';
const isRadar = rawSource.startsWith('Radar_') || rawSource === 'Radar';
const isWhatsApp = rawSource === 'WhatsApp';
const isTelegram = rawSource === 'Telegram_Bot';
const isForm = rawSource === 'Website_Form' || rawSource === 'Form';

// ── Base score by source ──────────────────────────────────────────────────────
// Radar already pre-scored by AI; use that as base if available
let base_score = 5;
if (isRadar) {
  base_score = Math.min(lead.lead_quality || 20, 50); // cap Radar base at 50
} else if (isWhatsApp || isTelegram) {
  base_score = 20; // direct inbound = strong intent signal
} else if (isForm) {
  base_score = 15;
}

// ── Extract core fields ───────────────────────────────────────────────────────
const phone = lead.phone || 'unknown';
const name = lead.full_name || 'غير معروف';
const message = lead.message || lead.raw_text || lead.clean_text || '';
const email = lead.email || '';

// ── Radar AI data (if available) ─────────────────────────────────────────────
const radar_intent = lead.intent || lead.radar_intent || '';
const radar_urgency = lead.urgency || lead.radar_urgency || '';
const radar_quality = lead.lead_quality || lead.radar_quality || 0;
const budget_signal = lead.budget_signal || 'unknown';
const travel_group = lead.travel_group || 'unknown';
const stars_preference = lead.stars_preference || 'unknown';
const has_phone = lead.has_phone || (lead.phones_found || []).length > 0;
const pax_hint = lead.pax_hint || 0;


// SaaSAI – Service Type Detection
const svcKeywords = {
  automation: ['أتمتة','n8n','workflow','make','zapier','اوتوماشن'],
  ai_solutions: ['ذكاء اصطناعي','ai','chatgpt','claude','gemini'],
  web_dev: ['موقع','website','wordpress','تطبيق','متجر'],
  seo: ['seo','محركات البحث','جوجل','ترتيب'],
  design: ['تصميم','جرافيك','هوية','لوجو','شعار'],
  video: ['فيديو','موشن','reels','مونتاج'],
  marketing: ['تسويق','marketing','إعلان','ads','سوشيال'],
  content: ['محتوى','مقال','كتابة','content'],
  training: ['تدريب','كورس','دورة','training'],
  wedding: ['زفاف','دعوة','عرس','wedding','مناسبة','invitation'],
};
const msgLower = message.toLowerCase();
let service_type = lead.service_type || lead.radar_intent || 'general';
for (const [svc, kws] of Object.entries(svcKeywords)) {
  if (kws.some(k => msgLower.includes(k))) { service_type = svc; break; }
}

return [{ json: { service_type,
  phone,
  name,
  email,
  message,
  source: rawSource,
  is_radar: isRadar,
  is_direct_inbound: isWhatsApp || isTelegram,
  base_score,
  radar_intent,
  radar_urgency,
  radar_quality,
  budget_signal,
  travel_group,
  stars_preference,
  has_phone,
  pax_hint,
  phones_found: lead.phones_found || [],
  content_hash: lead.content_hash || '',
  received_at: lead.received_at || new Date().toISOString(),
  raw: lead
} }];

// ─── Base Score + Loyalty + Radar Urgency Bonus ──────────────────────────────
const data = $('Code – Normalize Lead for Scoring').first().json;
const history = $input.all().map(i => i.json).filter(h => h && h.phone);

// ── Loyalty bonus (repeat interaction) ───────────────────────────────────────
const interaction_count = history.length;
const loyalty_bonus = Math.min(interaction_count * 5, 20); // max 20 pts

// ── Radar AI urgency bonus ────────────────────────────────────────────────────
let urgency_bonus = 0;
if (data.radar_urgency === 'immediate') urgency_bonus = 25;
else if (data.radar_urgency === 'soon') urgency_bonus = 12;
else if (data.radar_urgency === 'planned') urgency_bonus = 5;

// ── Radar intent bonus ────────────────────────────────────────────────────────
let intent_bonus = 0;
if (data.radar_intent === 'booking_ready') intent_bonus = 30;
else if (data.radar_intent === 'complaint_competitor') intent_bonus = 20;
else if (data.radar_intent === 'booking_research') intent_bonus = 10;
else if (data.radar_intent === 'travel_planning') intent_bonus = 5;

// ── Phone signal bonus ────────────────────────────────────────────────────────
const phone_bonus = data.has_phone ? 15 : 0;

// ── Budget/Stars bonus ────────────────────────────────────────────────────────
let budget_bonus = 0;
if (data.budget_signal === 'luxury') budget_bonus = 8;
else if (data.budget_signal === 'mid') budget_bonus = 5;

let stars_bonus = 0;
if (data.stars_preference === '5star') stars_bonus = 8;
else if (data.stars_preference === '4star') stars_bonus = 5;

// ── Direct inbound bonus (WhatsApp / Telegram contact) ───────────────────────
const inbound_bonus = data.is_direct_inbound ? 20 : 0;

const subtotal = data.base_score + loyalty_bonus + urgency_bonus + intent_bonus + phone_bonus + budget_bonus + stars_bonus + inbound_bonus;

return [{ json: {
  ...data,
  interaction_count,
  loyalty_bonus,
  urgency_bonus,
  intent_bonus,
  phone_bonus,
  budget_bonus,
  stars_bonus,
  inbound_bonus,
  subtotal
} }];

// Check for urgency keywords and set boolean flag
const items = $input.all();
return items.map(item => {
  const msg = (item.json.message || item.json.raw_text || '').toLowerCase();
  const urgencyKWs = ['عاجل','حالا','الآن','اليوم','حجز فوري','متاح','فوراً','هذا الأسبوع','قريباً','سريع','urgent','now','today','asap'];
  const has_urgency_kw = urgencyKWs.some(kw => msg.includes(kw));
  return { json: { ...item.json, has_urgency_kw } };
});

// B2B detected: +35 pts, classify as B2B
const msg = $json.message || '';
let b2b_type = 'B2B_agency';
if (msg.match(/حكوم|وزار|هيئة|government/i)) b2b_type = 'B2B_government';
else if (msg.match(/مؤتمر|conference/i)) b2b_type = 'B2B_conference';

return [{ json: { ...$json, b2b_bonus: 35, lead_category: b2b_type } }];

// Not B2B – classify as B2C, check group size
const pax = $json.pax_hint || 0;
const tg = $json.travel_group || 'unknown';
let lead_category = 'B2C_solo';
if (pax >= 10 || tg === 'group') lead_category = 'B2C_large_group';
else if (pax >= 4 || tg === 'family') lead_category = 'B2C_family';
else if (pax === 2 || tg === 'couple') lead_category = 'B2C_couple';

return [{ json: { ...$json, b2b_bonus: 0, lead_category } }];

// ─── Add Group Bonus if Large Group (True branch) v2.3 ────────────────────────
// هذه العقدة تُنفذ فقط إذا مرّ الشرط في IF السابقة
// لكن نضيف تحقق إضافي للأمان (defense in depth)

const pax = $json.pax_hint || 0;
const groupType = $json.travel_group || 'unknown';

const isLarge = pax > 6 || groupType === 'group' || (groupType === 'family' && pax >= 4);

return [{
  json: {
    ...$json,  // نحافظ على كل الحقول الأصلية
    group_bonus: isLarge ? 20 : 0,  // فقط إذا كانت مجموعة كبيرة فعلاً
    // تحديث lead_category إذا لم يكن موجوداً من قبل
    lead_category: $json.lead_category || (isLarge ? 'B2C_large_group' : 'B2C')
  }
}];

// ─── Final Score Calculation & Classification ─────────────────────────────
const d = $input.first().json;

const total = Math.min(
  (d.base_score || 0) +
  (d.loyalty_bonus || 0) +
  (d.urgency_bonus || 0) +
  (d.intent_bonus || 0) +
  (d.phone_bonus || 0) +
  (d.budget_bonus || 0) +
  (d.stars_bonus || 0) +
  (d.inbound_bonus || 0) +
  (d.kw_urgency_bonus || 0) +
  (d.b2b_bonus || 0) +
  (d.group_bonus || 0),
  100
);

// ── Status classification ─────────────────────────────────────────────────────
let status = 'Cold';
let priority = 3;
if (total >= 80) { status = 'Hot'; priority = 1; }
else if (total >= 55) { status = 'Warm'; priority = 2; }

// ── Next action recommendation ────────────────────────────────────────────────
let recommended_action = 'nurture_sequence';
if (status === 'Hot') {
  if (d.lead_category?.startsWith('B2B')) recommended_action = 'b2b_sales_call';
  else recommended_action = 'immediate_sales_call';
} else if (status === 'Warm') {
  recommended_action = 'whatsapp_followup_24h';
}

// ── Score breakdown for transparency ─────────────────────────────────────────
const breakdown = {
  base: d.base_score || 0,
  loyalty: d.loyalty_bonus || 0,
  urgency_ai: d.urgency_bonus || 0,
  urgency_kw: d.kw_urgency_bonus || 0,
  intent: d.intent_bonus || 0,
  phone: d.phone_bonus || 0,
  budget: d.budget_bonus || 0,
  stars: d.stars_bonus || 0,
  inbound: d.inbound_bonus || 0,
  b2b: d.b2b_bonus || 0,
  group: d.group_bonus || 0
};

return [{ json: {
  ...d,
  final_score: total,
  status,
  priority,
  lead_category: d.lead_category || 'B2C_solo',
  recommended_action,
  score_breakdown: breakdown,
  scored_at: new Date().toISOString()
} }];

